def find_unique_char_position(S):
    # 最初の3文字をチェックして異なる文字を特定
    if S[0] == S[1]:
        common_char = S[0]
    elif S[0] == S[2]:
        common_char = S[0]
    else:
        common_char = S[1]

    # 異なる1文字の位置を特定
    for i, char in enumerate(S):
        if char != common_char:
            return i + 1  # 1-based index
